insert into change_headers (id, ts) values (63, '2026-09-01') on duplicate key update ts = values(ts);
insert into change_descriptions (id, lang, description) values (63, 'ru', 'Калькулятор торговли: покупку теперь можно разделить по проценту от продаваемого ресурса, а не от получаемого. При продаже 1 000 000 дейтерия с долей 50 % металл и кристалл считаются как половины по 500 000 дейтерия.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (63, 'en', 'Trade calculator: a purchase can now be split by a percentage of the resource being sold, not of the one received. Selling 1,000,000 Deuterium with a 50% share counts Metal and Crystal as halves of 500,000 Deuterium each.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (63, 'pt', 'Calculadora de comércio: uma compra agora pode ser dividida por uma percentagem do recurso vendido, e não do recebido. Ao vender 1.000.000 de Deutério com uma quota de 50%, o Metal e o Cristal são contados como metades de 500.000 de Deutério cada.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (63, 'de', 'Handelsrechner: Ein Kauf kann jetzt nach einem Prozentsatz der verkauften Ressource aufgeteilt werden, nicht der erhaltenen. Beim Verkauf von 1.000.000 Deuterium mit einem Anteil von 50 % werden Metall und Kristall jeweils als Hälften von 500.000 Deuterium gerechnet.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (63, 'pl', 'Kalkulator handlu: zakup można teraz podzielić według procentu sprzedawanego surowca, a nie otrzymywanego. Przy sprzedaży 1.000.000 Deuteru z udziałem 50% Metal i Kryształ liczone są jako połowy po 500.000 Deuteru.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (63, 'es', 'Calculadora de comercio: una compra ahora se puede dividir por un porcentaje del recurso vendido, no del recibido. Al vender 1.000.000 de Deuterio con una cuota del 50%, el Metal y el Cristal se cuentan como mitades de 500.000 de Deuterio cada uno.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (63, 'fr', 'Calculateur de commerce : un achat peut désormais être réparti selon un pourcentage de la ressource vendue, et non de celle reçue. En vendant 1 000 000 de Deutérium avec une part de 50 %, le Métal et le Cristal sont comptés comme des moitiés de 500 000 de Deutérium chacun.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (63, 'it', 'Calcolatore del commercio: un acquisto ora può essere suddiviso in base a una percentuale della risorsa venduta, non di quella ricevuta. Vendendo 1.000.000 di Deuterio con una quota del 50%, Metallo e Cristallo vengono contati come metà di 500.000 di Deuterio ciascuno.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (63, 'nl', 'Handelscalculator: een aankoop kan nu worden verdeeld op basis van een percentage van de verkochte grondstof, niet van de ontvangen grondstof. Bij het verkopen van 1.000.000 Deuterium met een aandeel van 50% worden Metaal en Kristal elk geteld als helften van 500.000 Deuterium.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (63, 'sk', 'Kalkulačka obchodu: nákup je teraz možné rozdeliť podľa percenta predávanej suroviny, nie prijímanej. Pri predaji 1 000 000 Deutéria s podielom 50 % sa Kov a Kryštál počítajú ako polovice po 500 000 Deutéria.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (63, 'tr', 'Ticaret hesaplayıcısı: bir satın alma artık alınan kaynağa göre değil, satılan kaynağın yüzdesine göre bölünebilir. %50 pay ile 1.000.000 Döteryum satıldığında Metal ve Kristal, her biri 500.000 Döteryumun yarısı olarak hesaplanır.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (63, 'bs', 'Kalkulator trgovine: kupovina se sada može podijeliti prema postotku resursa koji se prodaje, a ne onog koji se prima. Pri prodaji 1.000.000 Deuterijuma s udjelom od 50%, Metal i Kristal se računaju kao polovine od po 500.000 Deuterijuma.') on duplicate key update description = values(description);
